WITH ValidDepartments AS (SELECT * FROM departments WHERE dept_name != 'Sales'), departments_stats AS (SELECT location, CASE WHEN budget >= 3201000 THEN 'high' WHEN budget >= 1838000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(CASE WHEN location = 'Singapore' THEN budget ELSE 0 END) AS singapore_budget, COUNT(*) AS total_count FROM ValidDepartments GROUP BY location, CASE WHEN budget >= 3201000 THEN 'high' WHEN budget >= 1838000 THEN 'mid' ELSE 'low' END) SELECT * FROM departments_stats ORDER BY singapore_budget DESC, total_count DESC;
